body.t-artdeco .hero h1 { text-transform: uppercase; font-weight: 400; }
body.t-artdeco .hero h1::after {
  content: ""; display: block; width: 180px; height: 12px; margin: 18px auto 0;
  background:
    linear-gradient(90deg, transparent 0 38%, var(--accent) 38% 62%, transparent 62%),
    linear-gradient(90deg, var(--accent), var(--accent));
  background-size: 100% 2px, 100% 1px; background-position: 0 8px, 0 3px; background-repeat: no-repeat;
}
